<template><Card class="s45-manager"><template v-if="!$route.params.id"><h2>收付通渠道关系</h2><p class="intro">核对店铺、平台、二级商户与佣金接收关系。Mock 与真实渠道分别标明，当前关系变化不改写历史订单。</p><RecordList endpoint="/channels" :dated="false" :columns="columns" @open="open"/></template><template v-else><Button @click="back">返回列表</Button><Button :loading="loading" @click="load">重新读取</Button><Alert v-if="error" type="error" show-icon>{{error}}<p v-if="detail">保留最后已知事实；本次读取失败，以下状态需重新核验。</p></Alert><OperationRecovery :name="'channel:'+$route.params.id" :revision="revision" @recovered="load"/><template v-if="detail"><h2>{{detail.storeName}}</h2><section class="detail-section"><h3>当前渠道主体</h3><dl class="facts"><div v-for="row in facts" :key="row[0]" class="fact"><dt>{{row[0]}}</dt><dd>{{row[1]}}</dd></div></dl></section><section class="detail-section"><h3>分别核对渠道能力</h3><dl class="facts"><div v-for="item in capabilities" :key="item.key" class="fact"><dt>{{item.title}}</dt><dd>{{label(detail.capabilities[item.key])}}<template v-if="detail.capabilityChecks && detail.capabilityChecks[item.key]"><p class="meta">{{detail.capabilityChecks[item.key].reason}}</p><p class="meta">核验时间：{{detail.capabilityChecks[item.key].verifiedAt ? date(detail.capabilityChecks[item.key].verifiedAt) : '尚无核验时刻'}}</p></template></dd></div></dl><p class="meta">能力来源为当前模式对应的受控渠道证据；本地资格不等于真实账户及原交易可执行。真实接入另行核验。</p></section><Form v-if="detail.canSync" label-position="top"><FormItem label="查询同步原因 *"><Input v-model="reason" type="textarea" :maxlength="500" placeholder="说明核对原因"/></FormItem><Button type="primary" :loading="busy" :disabled="pending" @click="sync">查询并同步当前关系</Button></Form><h3>核验历史</h3><div class="history" v-for="(row,index) in detail.history" :key="index"><p>{{label(row.state)}} · {{date(row.at)}}</p></div><p class="meta">原关系进件、启停及维护沿用既有入口和权限；本页同步不改变订单历史主体。</p></template></template></Card></template>
<script>
import RecordList from './components/RecordList.vue';import OperationRecovery from './components/OperationRecovery.vue';import {s45Read,s45Commands} from '@/api/stage45';import {managerSession} from '@/libs/manager-session';import {label,date} from './presentation.cjs';
export default{components:{RecordList,OperationRecovery},data(){return{detail:null,reason:'',busy:false,loading:false,error:'',ticket:0,revision:0,capabilities:[{key:'onboarding',title:'进件'},{key:'payment',title:'收款'},{key:'profitsharing',title:'分账'},{key:'refund',title:'退款'},{key:'return',title:'分账回退'},{key:'bill',title:'账单'}],columns:[{title:'店铺',key:'storeName',minWidth:200},{title:'二级商户',key:'subMerchant',minWidth:150},{title:'模式',minWidth:130,render:(h,{row})=>h('span',label(row.mode))},{title:'当前关系',minWidth:140,render:(h,{row})=>h('span',row.replaced?'历史关系':row.enabled?'已启用':'未启用')},{title:'最后核验',minWidth:190,render:(h,{row})=>h('span',date(row.verifiedAt))}]}},computed:{pending(){this.revision;return s45Commands.pending('channel:'+this.$route.params.id)},facts(){const d=this.detail;return [['店铺编号',d.storeId],['渠道关系编号 / 版本',d.id+' / '+d.version],['渠道模式',label(d.mode)],['平台商户',d.platformMerchant],['二级商户',d.subMerchant],['佣金接收关系',d.receiverName||'未核实'],['关系状态',d.replaced?'历史关系':d.enabled?'已启用':'未启用'],['最后核验',date(d.verifiedAt)]]}},watch:{'$route.params.id':{handler(){if(this.$route.params.id)this.load();else{this.ticket++;this.detail=null}},immediate:true}},beforeDestroy(){this.ticket++;this.detail=null},methods:{date,label,open(row){this.$router.push({path:'/s45/channels/'+row.id,query:this.$route.query})},back(){this.$router.push({path:'/s45/channels',query:this.$route.query})},async load(){if(!this.$route.params.id)return;const ticket=++this.ticket,owner=managerSession.snapshot();this.loading=true;this.error='';try{const v=await s45Read('/channels/'+this.$route.params.id);if(ticket===this.ticket&&managerSession.sameSession(owner))this.detail=v}catch(e){if(ticket===this.ticket){this.error=e.message;if(e.status===401||e.status===403||e.code==='STALE_OPERATION'||!managerSession.sameSession(owner))this.detail=null}}finally{if(ticket===this.ticket)this.loading=false}},sync(){if(this.reason.trim().length<2){this.error='请填写至少2字的核对原因。';return}this.$Modal.confirm({title:'查询同步当前渠道关系',content:'核对当前能力及时间，保留原订单的历史身份。',onOk:async()=>{this.busy=true;this.error='';try{await s45Commands.run('channel:'+this.detail.id,'/channels/'+this.detail.id+'/sync',{expectedVersion:this.detail.version,reason:this.reason.trim()});this.load()}catch(e){this.error=e.message}finally{this.revision++;this.busy=false}}})}}};
</script><style lang="scss">@import './stage45.scss';</style>
